function useTheme() {
  const [dark, setDark] = useState(() => {
    const saved = localStorage.getItem("cn-theme");
    return saved ? saved === "dark" : window.matchMedia?.("(prefers-color-scheme: dark)").matches ?? false;
  });
  useEffect(() => { document.documentElement.classList.toggle("dark", dark); localStorage.setItem("cn-theme", dark ? "dark" : "light"); }, [dark]);
  return [dark, () => setDark((v) => !v)] as const;
}
function useLocalList(key: string) {
  const [items, setItems] = useState<string[]>(() => { try { return JSON.parse(localStorage.getItem(key) || "[]"); } catch { return []; } });
  const save = (next: string[]) => { setItems(next); localStorage.setItem(key, JSON.stringify(next)); };
  return [items, save] as const;
}
function useMeta(title: string, description: string) {
  useEffect(() => { document.title = `${title} · CalcNova`; let meta = document.querySelector('meta[name="description"]'); if (!meta) { meta = document.createElement("meta"); meta.setAttribute("name", "description"); document.head.appendChild(meta); } meta.setAttribute("content", description); }, [title, description]);
}

