function CalcCard({ calc, favorite, onFavorite }: { calc: Calc; favorite: boolean; onFavorite: () => void }) {
  const Icon = calc.icon;
  return <div className="cn-calc-card" data-testid={`card-calculator-${calc.slug}`}><Link href={`/calculator/${calc.slug}`} style={{ display: "flex", flexDirection: "column", flex: 1 }} data-testid={`link-calculator-${calc.slug}`}><span className="cn-card-icon"><Icon size={19} /></span><span style={{ marginTop: "auto" }}><h3>{calc.title}</h3><p>{calc.description}</p></span></Link><div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}><span className="cn-kicker" style={{ fontSize: ".58rem" }}>{calc.category}</span><button className="cn-icon-btn" style={{ width: 30, height: 30, border: 0 }} onClick={onFavorite} aria-label={favorite ? `Remove ${calc.title} from favorites` : `Favorite ${calc.title}`} data-testid={`button-favorite-${calc.slug}`}><Star size={16} fill={favorite ? "currentColor" : "none"} /></button></div></div>;
}
function getRecommended(calc: Calc) {
  const sameCategory = CALCS.filter((item) => item.category === calc.category && item.slug !== calc.slug);
  return sameCategory[0] || CALCS[(CALCS.findIndex((item) => item.slug === calc.slug) + 1) % CALCS.length];
}

