  useMeta("Calculator directory", "Browse every CalcNova calculator by category.");
  const [location] = useLocation();
  const params = new URLSearchParams(location.split("?")[1] || "");
  const [query, setQuery] = useState(params.get("q") || ""); const [category, setCategory] = useState(params.get("category") || "All"); const [favorites, setFavorites] = useLocalList("cn-favorites");
  const results = useMemo(() => CALCS.filter((c) => (category === "All" || c.category === category) && `${c.title} ${c.description}`.toLowerCase().includes(query.toLowerCase())), [query, category]);
  const toggle = (slug: string) => setFavorites(favorites.includes(slug) ? favorites.filter((x) => x !== slug) : [...favorites, slug]);
  const recommended = results[0] || CALCS.find((calc) => calc.category === "Everyday") || CALCS[0];
  return <Shell><div className="cn-container"><div className="cn-page-title"><div className="cn-hero-badge"><Sparkles size={14} /> {CALCS.length} tools, zero signup</div><SectionLabel>CalcNova directory</SectionLabel><h1 className="cn-display">Find your next<br /><span style={{ color: "hsl(var(--primary))" }}>answer.</span></h1><p>One focused tool for every ordinary question. Search by what you want to solve, not by what the formula is called.</p></div><div className="cn-search"><Search size={19} /><label className="cn-sr-only" htmlFor="calculator-search">Search calculators</label><input id="calculator-search" type="search" placeholder="Try “loan”, “height”, or “tip”" value={query} onChange={(e) => setQuery(e.target.value)} data-testid="input-calculator-search" /></div><div className="cn-recommendation"><div><span className="cn-kicker">You might also like</span><strong>{recommended.title}</strong><p>{recommended.description}</p></div><Link href={`/calculator/${recommended.slug}`} className="cn-button cn-button-soft">Open tool <ArrowRight size={15} /></Link></div><div className="cn-category-tabs" aria-label="Calculator categories">{CATEGORIES.map((c) => <button key={c} className={`cn-chip ${category === c ? "active" : ""}`} onClick={() => setCategory(c)} data-testid={`button-category-${c.toLowerCase().replace(/\W/g, "-")}`}>{c}<span>{c === "All" ? CALCS.length : CALCS.filter((calc) => calc.category === c).length}</span></button>)}</div><div className="cn-directory-layout"><aside><div className="cn-kicker" style={{ marginBottom: 10 }}>Browse by category</div><div className="cn-categories">{CATEGORIES.map((c) => <button key={c} className={`cn-chip ${category === c ? "active" : ""}`} onClick={() => setCategory(c)}>{c}<span>{c === "All" ? CALCS.length : CALCS.filter((calc) => calc.category === c).length}</span></button>)}</div><div className="cn-side-note"><HeartPulse size={17} /><strong>Health tools?</strong><span>Tap Health to see every wellness calculator together.</span></div></aside><section><div className="cn-section-head" style={{ marginBottom: 15 }}><span style={{ color: "hsl(var(--muted-foreground))", fontSize: ".8rem" }}>{results.length} {results.length === 1 ? "calculator" : "calculators"}</span><span className="cn-mono" style={{ color: "hsl(var(--muted-foreground))", fontSize: ".7rem" }}>LOCAL / PRIVATE</span></div>{results.length ? <div className="cn-grid">{results.map((calc) => <CalcCard key={calc.slug} calc={calc} favorite={favorites.includes(calc.slug)} onFavorite={() => toggle(calc.slug)} />)}</div> : <div className="cn-empty" style={{ border: "1px dashed hsl(var(--border))", borderRadius: 16 }}><Search size={26} style={{ marginBottom: 10 }} /><div>No calculators match that search.</div><button className="cn-button cn-button-soft" style={{ marginTop: 14 }} onClick={() => { setQuery(""); setCategory("All"); }} data-testid="button-clear-search">Clear search</button></div>}</section></div></div></Shell>;
