function GST() { const calc = CALCS[4]; const [amount, setAmount] = useState("1000"); const [rate, setRate] = useState("18"); const [mode, setMode] = useState("add"); const tax = n(amount) * n(rate) / 100; const total = mode === "add" ? n(amount) + tax : n(amount); const base = mode === "add" ? n(amount) : n(amount) / (1 + n(rate) / 100); const gst = mode === "add" ? tax : n(amount) - base; return <Frame calc={calc} onReset={() => { setAmount(""); setRate("18"); }} result={<Result label={mode === "add" ? "Price with GST" : "Price before GST"} value={`₹ ${total === 0 ? "0" : (mode === "add" ? total : base).toFixed(2)}`} rows={[["Base amount", `₹ ${base.toFixed(2)}`], ["GST amount", `₹ ${gst.toFixed(2)}`], ["GST rate", `${rate}%`]]} formula={mode === "add" ? "amount + (amount × rate ÷ 100)" : "inclusive price ÷ (1 + rate)"}/>}><div className="cn-toggle-row"><button className={`cn-toggle ${mode === "add" ? "active" : ""}`} onClick={() => setMode("add")} data-testid="button-gst-add">Add GST</button><button className={`cn-toggle ${mode === "remove" ? "active" : ""}`} onClick={() => setMode("remove")} data-testid="button-gst-remove">Remove GST</button></div><div className="cn-field-grid two" style={{ marginTop: 20 }}><Field label="Amount" value={amount} onChange={setAmount} /><Field label="GST rate (%)" value={rate} onChange={setRate} /></div><div className="cn-toggle-row" style={{ marginTop: 15 }}>{["5", "12", "18", "28"].map((x) => <button className="cn-toggle" key={x} onClick={() => setRate(x)} data-testid={`button-gst-rate-${x}`}>{x}%</button>)}</div></Frame>; }
