function Age() { const calc = CALCS[6]; const [dob, setDob] = useState("1995-06-15"); const birth = new Date(`${dob}T00:00:00`); const now = new Date(); const valid = Number.isFinite(birth.getTime()); let years = valid ? now.getFullYear() - birth.getFullYear() : 0; let months = valid ? now.getMonth() - birth.getMonth() : 0; let days = valid ? now.getDate() - birth.getDate() : 0; if (days < 0) { months--; days += new Date(now.getFullYear(), now.getMonth(), 0).getDate(); } if (months < 0) { years--; months += 12; } const totalDays = valid ? Math.max(0, Math.floor((now.getTime() - birth.getTime()) / 86400000)) : 0; const next = valid ? new Date(now.getFullYear(), birth.getMonth(), birth.getDate()) : now; if (next < now) next.setFullYear(now.getFullYear() + 1); const until = valid ? Math.max(0, Math.ceil((next.getTime() - now.getTime()) / 86400000)) : 0; return <Frame calc={calc} onReset={() => setDob("")} result={<Result label="Your age" value={valid ? `${Math.max(0, years)}y ${Math.max(0, months)}m ${Math.max(0, days)}d` : "Enter a date"} rows={[["Total days lived", totalDays.toLocaleString()], ["Next birthday", valid ? `${until} days away` : "—"]]} note="Age is calculated from your local date and time." />}><Field label="Date of birth" type="date" value={dob} onChange={setDob} /></Frame>; }
