const calcFor = (slug: string) => CALCS.find((calc) => calc.slug === slug)!;
const gcd = (a: number, b: number): number => b ? gcd(b, a % b) : Math.abs(a) || 1;
const listNumbers = (value: string) => value.split(",").map((part) => Number(part.trim())).filter((part) => Number.isFinite(part));

function Fraction() {
  const calc = calcFor("fraction-calculator"); const [a, setA] = useState("1"); const [b, setB] = useState("2"); const [c, setC] = useState("1"); const [d, setD] = useState("4"); const [op, setOp] = useState("+");
  const left = n(a) / (n(b) || 1), right = n(c) / (n(d) || 1); const decimal = op === "+" ? left + right : op === "−" ? left - right : op === "×" ? left * right : right ? left / right : 0; const numerator = op === "+" ? n(a) * (n(d) || 1) + n(c) * (n(b) || 1) : op === "−" ? n(a) * (n(d) || 1) - n(c) * (n(b) || 1) : op === "×" ? n(a) * n(c) : n(a) * (n(d) || 1); const denominator = op === "÷" ? (n(b) || 1) * (n(c) || 1) : op === "×" ? (n(b) || 1) * (n(d) || 1) : (n(b) || 1) * (n(d) || 1); const divisor = gcd(Math.round(numerator), Math.round(denominator)); const fraction = `${Math.round(numerator / divisor)}/${Math.round(denominator / divisor)}`;
  return <Frame calc={calc} onReset={() => { setA(""); setB(""); setC(""); setD(""); }} result={<Result label="Simplified result" value={fraction} rows={[["Decimal", Number.isFinite(decimal) ? decimal.toFixed(4) : "Enter valid values"], ["Expression", `${a}/${b} ${op} ${c}/${d}`]]} formula="common denominator, then simplify by the greatest common divisor" />}><div className="cn-toggle-row"><span className="cn-kicker" style={{ alignSelf: "center" }}>Operation</span>{["+","−","×","÷"].map((item) => <button className={`cn-toggle ${op === item ? "active" : ""}`} key={item} onClick={() => setOp(item)}>{item}</button>)}</div><div className="cn-fraction-inputs"><div><Field label="Numerator" value={a} onChange={setA} /><div className="cn-fraction-line" /><Field label="Denominator" value={b} onChange={setB} /></div><span className="cn-fraction-op">{op}</span><div><Field label="Numerator" value={c} onChange={setC} /><div className="cn-fraction-line" /><Field label="Denominator" value={d} onChange={setD} /></div></div></Frame>;
}
function Average() {
  const calc = calcFor("average-calculator"); const [values, setValues] = useState("12, 18, 24, 30"); const nums = listNumbers(values); const total = nums.reduce((sum, value) => sum + value, 0); const average = nums.length ? total / nums.length : 0;
  return <Frame calc={calc} onReset={() => setValues("")} result={<Result label="Average" value={nums.length ? average.toFixed(2) : "Enter numbers"} rows={[["Total", total.toFixed(2)], ["Count", String(nums.length)], ["Range", nums.length ? `${Math.min(...nums)} – ${Math.max(...nums)}` : "—"]]} formula="sum of values ÷ number of values" />}><Field label="Numbers separated by commas" type="text" value={values} onChange={setValues} placeholder="12, 18, 24, 30" /></Frame>;
}
function Ratio() {
  const calc = calcFor("ratio-calculator"); const [a, setA] = useState("2"); const [b, setB] = useState("3"); const [part, setPart] = useState("10"); const scale = n(a) ? n(part) / n(a) : 0; const other = n(b) * scale; const divisor = gcd(Math.round(n(a)), Math.round(n(b)));
  return <Frame calc={calc} onReset={() => { setA(""); setB(""); setPart(""); }} result={<Result label="Scaled ratio" value={`${part || 0} : ${other.toFixed(2)}`} rows={[["Simplified ratio", `${Math.round(n(a) / divisor)} : ${Math.round(n(b) / divisor)}`], ["Scale factor", scale.toFixed(2)]]} formula="second part × (target first part ÷ first part)" />}><div className="cn-field-grid two"><Field label="First part" value={a} onChange={setA} /><Field label="Second part" value={b} onChange={setB} /><Field label="Target first part" value={part} onChange={setPart} /></div></Frame>;
}
function Scientific() {
  const calc = calcFor("scientific-calculator"); const [value, setValue] = useState("45"); const [operation, setOperation] = useState("sin"); const x = n(value); const answer = operation === "sin" ? Math.sin(x * Math.PI / 180) : operation === "cos" ? Math.cos(x * Math.PI / 180) : operation === "tan" ? Math.tan(x * Math.PI / 180) : operation === "sqrt" ? Math.sqrt(x) : operation === "log" ? Math.log10(x) : operation === "square" ? x * x : Math.pow(x, 3);
  return <Frame calc={calc} onReset={() => setValue("")} result={<Result label="Result" value={Number.isFinite(answer) ? answer.toFixed(6) : "Enter a valid value"} rows={[["Input", value || "—"], ["Operation", operation]]} formula="trigonometry uses degrees; logarithm is base 10" />}><div className="cn-field-grid two"><Field label="Value" value={value} onChange={setValue} /><SelectField label="Operation" value={operation} onChange={setOperation} options={[{ value: "sin", label: "sin (degrees)" }, { value: "cos", label: "cos (degrees)" }, { value: "tan", label: "tan (degrees)" }, { value: "sqrt", label: "Square root" }, { value: "log", label: "Log base 10" }, { value: "square", label: "Square" }, { value: "cube", label: "Cube" }]} /></div></Frame>;
}
function Loan() {
  const calc = calcFor("loan-calculator"); const [principal, setPrincipal] = useState("500000"); const [rate, setRate] = useState("9"); const [years, setYears] = useState("5"); const months = n(years) * 12; const monthlyRate = n(rate) / 1200; const payment = monthlyRate ? n(principal) * monthlyRate * Math.pow(1 + monthlyRate, months) / (Math.pow(1 + monthlyRate, months) - 1) : months ? n(principal) / months : 0; const total = payment * months;
  return <Frame calc={calc} onReset={() => { setPrincipal(""); setRate(""); setYears(""); }} result={<Result label="Monthly payment" value={`₹ ${payment.toLocaleString("en-IN", { maximumFractionDigits: 0 })}`} rows={[["Total interest", `₹ ${Math.max(0, total - n(principal)).toLocaleString("en-IN", { maximumFractionDigits: 0 })}`], ["Total repayment", `₹ ${total.toLocaleString("en-IN", { maximumFractionDigits: 0 })}`], ["Payments", String(months)]]} formula="reducing-balance monthly payment formula" />}><div className="cn-field-grid"><Field label="Loan amount" value={principal} onChange={setPrincipal} /><Field label="Annual interest rate (%)" value={rate} onChange={setRate} /><Field label="Loan tenure (years)" value={years} onChange={setYears} /></div></Frame>;
}
function Savings() {
  const calc = calcFor("savings-calculator"); const [goal, setGoal] = useState("100000"); const [current, setCurrent] = useState("10000"); const [monthly, setMonthly] = useState("5000"); const [years, setYears] = useState("2"); const months = n(years) * 12; const planned = n(current) + n(monthly) * months; const remaining = Math.max(0, n(goal) - n(current)); const needed = months ? remaining / months : remaining;
  return <Frame calc={calc} onReset={() => { setGoal(""); setCurrent(""); setMonthly(""); setYears(""); }} result={<Result label="Goal check" value={planned >= n(goal) ? "On track" : `₹ ${needed.toFixed(0)} / month`} rows={[["Projected total", `₹ ${planned.toLocaleString("en-IN")}`], ["Still needed", `₹ ${Math.max(0, n(goal) - planned).toLocaleString("en-IN")}`], ["Time", `${months} months`]]} note="A simple planning estimate with no investment return assumed." />}><div className="cn-field-grid"><Field label="Savings goal" value={goal} onChange={setGoal} /><Field label="Already saved" value={current} onChange={setCurrent} /><Field label="Monthly saving" value={monthly} onChange={setMonthly} /><Field label="Time period (years)" value={years} onChange={setYears} /></div></Frame>;
}
function Tax() {
  const calc = calcFor("tax-calculator"); const [amount, setAmount] = useState("50000"); const [rate, setRate] = useState("18"); const [deductions, setDeductions] = useState("0"); const taxable = Math.max(0, n(amount) - n(deductions)); const tax = taxable * n(rate) / 100;
  return <Frame calc={calc} onReset={() => { setAmount(""); setRate(""); setDeductions("0"); }} result={<Result label="After-tax amount" value={`₹ ${(n(amount) - tax).toFixed(2)}`} rows={[["Taxable amount", `₹ ${taxable.toFixed(2)}`], ["Estimated tax", `₹ ${tax.toFixed(2)}`], ["Rate", `${rate}%`]]} note="This is a general estimate, not a tax filing or professional tax advice." />}><div className="cn-field-grid"><Field label="Income or price" value={amount} onChange={setAmount} /><Field label="Tax rate (%)" value={rate} onChange={setRate} /><Field label="Deductions" value={deductions} onChange={setDeductions} /></div></Frame>;
}
function Calorie() {
  const calc = calcFor("calorie-calculator"); const [age, setAge] = useState("25"); const [height, setHeight] = useState("170"); const [weight, setWeight] = useState("65"); const [sex, setSex] = useState("female"); const [activity, setActivity] = useState("1.55"); const bmr = sex === "male" ? 10 * n(weight) + 6.25 * n(height) - 5 * n(age) + 5 : 10 * n(weight) + 6.25 * n(height) - 5 * n(age) - 161; const calories = bmr * n(activity);
  return <Frame calc={calc} onReset={() => { setAge(""); setHeight(""); setWeight(""); }} result={<Result label="Daily calorie estimate" value={`${Math.round(calories).toLocaleString()} kcal`} rows={[["Resting needs", `${Math.round(bmr).toLocaleString()} kcal`], ["Activity level", activity === "1.2" ? "Sedentary" : activity === "1.55" ? "Moderate" : "Active"]]} note="General estimate only. Your needs can vary with health, goals, and routine." formula="Mifflin–St Jeor × activity level" />}><div className="cn-toggle-row"><button className={`cn-toggle ${sex === "female" ? "active" : ""}`} onClick={() => setSex("female")}>Female</button><button className={`cn-toggle ${sex === "male" ? "active" : ""}`} onClick={() => setSex("male")}>Male</button></div><div className="cn-field-grid two" style={{ marginTop: 18 }}><Field label="Age (years)" value={age} onChange={setAge} /><Field label="Height (cm)" value={height} onChange={setHeight} /><Field label="Weight (kg)" value={weight} onChange={setWeight} /><SelectField label="Activity level" value={activity} onChange={setActivity} options={[{ value: "1.2", label: "Sedentary" }, { value: "1.375", label: "Lightly active" }, { value: "1.55", label: "Moderately active" }, { value: "1.725", label: "Very active" }]} /></div></Frame>;
}
function IdealWeight() {
  const calc = calcFor("ideal-weight-calculator"); const [height, setHeight] = useState("170"); const lower = 18.5 * Math.pow(n(height) / 100, 2); const upper = 24.9 * Math.pow(n(height) / 100, 2);
  return <Frame calc={calc} onReset={() => setHeight("")} result={<Result label="General range" value={`${lower.toFixed(1)} – ${upper.toFixed(1)} kg`} rows={[["Height", `${height || 0} cm`], ["Lower BMI marker", "18.5"], ["Upper BMI marker", "24.9"]]} note="Weight ranges are broad screening references, not a personal health target." />}><Field label="Height (cm)" value={height} onChange={setHeight} /></Frame>;
}
function DaysBetween() {
  const calc = calcFor("days-between-calculator"); const [from, setFrom] = useState("2026-01-01"); const [to, setTo] = useState("2026-12-31"); const first = new Date(`${from}T00:00:00`); const second = new Date(`${to}T00:00:00`); const days = Number.isFinite(first.getTime()) && Number.isFinite(second.getTime()) ? Math.abs(Math.round((second.getTime() - first.getTime()) / 86400000)) : 0;
  return <Frame calc={calc} onReset={() => { setFrom(""); setTo(""); }} result={<Result label="Days between" value={`${days.toLocaleString()} days`} rows={[["Weeks", (days / 7).toFixed(1)], ["Months (approx.)", (days / 30.4375).toFixed(1)], ["Years (approx.)", (days / 365.25).toFixed(2)]]} note="The count uses your local calendar and includes leap-year dates." />}><div className="cn-field-grid two"><Field label="Start date" type="date" value={from} onChange={setFrom} /><Field label="End date" type="date" value={to} onChange={setTo} /></div></Frame>;
}
function TimeDuration() {
  const calc = calcFor("time-duration-calculator"); const [startHour, setStartHour] = useState("9"); const [startMinute, setStartMinute] = useState("30"); const [endHour, setEndHour] = useState("17"); const [endMinute, setEndMinute] = useState("45"); const start = n(startHour) * 60 + n(startMinute); const end = n(endHour) * 60 + n(endMinute); const duration = (end - start + 1440) % 1440;
  return <Frame calc={calc} onReset={() => { setStartHour(""); setStartMinute(""); setEndHour(""); setEndMinute(""); }} result={<Result label="Duration" value={`${Math.floor(duration / 60)}h ${duration % 60}m`} rows={[["Total minutes", String(duration)], ["Start", `${startHour || 0}:${String(startMinute || 0).padStart(2, "0")}`], ["End", `${endHour || 0}:${String(endMinute || 0).padStart(2, "0")}`]]} note="If the end time is earlier than the start, the calculator treats it as the next day." />}><div className="cn-time-block"><span className="cn-kicker">Start time</span><div className="cn-field-grid two"><Field label="Hours" value={startHour} onChange={setStartHour} /><Field label="Minutes" value={startMinute} onChange={setStartMinute} /></div></div><div className="cn-time-block"><span className="cn-kicker">End time</span><div className="cn-field-grid two"><Field label="Hours" value={endHour} onChange={setEndHour} /><Field label="Minutes" value={endMinute} onChange={setEndMinute} /></div></div></Frame>;
}
function FuelCost() {
  const calc = calcFor("fuel-cost-calculator"); const [distance, setDistance] = useState("250"); const [mileage, setMileage] = useState("15"); const [price, setPrice] = useState("105"); const litres = n(mileage) ? n(distance) / n(mileage) : 0; const cost = litres * n(price);
  return <Frame calc={calc} onReset={() => { setDistance(""); setMileage(""); setPrice(""); }} result={<Result label="Trip fuel cost" value={`₹ ${cost.toFixed(2)}`} rows={[["Fuel needed", `${litres.toFixed(2)} L`], ["Distance", `${distance || 0} km`], ["Fuel price", `₹ ${price || 0} / L`]]} formula="distance ÷ mileage × price per litre" />}><div className="cn-field-grid"><Field label="Trip distance (km)" value={distance} onChange={setDistance} /><Field label="Vehicle mileage (km/L)" value={mileage} onChange={setMileage} /><Field label="Fuel price (₹/L)" value={price} onChange={setPrice} /></div></Frame>;
}
function ElectricityCost() {
  const calc = calcFor("electricity-cost-calculator"); const [units, setUnits] = useState("100"); const [rate, setRate] = useState("8"); const [fixed, setFixed] = useState("100"); const cost = n(units) * n(rate) + n(fixed);
  return <Frame calc={calc} onReset={() => { setUnits(""); setRate(""); setFixed(""); }} result={<Result label="Estimated bill" value={`₹ ${cost.toFixed(2)}`} rows={[["Energy charge", `₹ ${(n(units) * n(rate)).toFixed(2)}`], ["Fixed charge", `₹ ${n(fixed).toFixed(2)}`], ["Usage", `${units || 0} kWh`]]} note="Actual bills can include slabs, taxes, and provider-specific charges." />}><div className="cn-field-grid"><Field label="Usage (kWh)" value={units} onChange={setUnits} /><Field label="Rate per kWh (₹)" value={rate} onChange={setRate} /><Field label="Fixed charge (₹)" value={fixed} onChange={setFixed} /></div></Frame>;
}
function SplitBill() {
  const calc = calcFor("split-bill-calculator"); const [bill, setBill] = useState("2400"); const [tip, setTip] = useState("10"); const [people, setPeople] = useState("4"); const tipAmount = n(bill) * n(tip) / 100; const total = n(bill) + tipAmount;
  return <Frame calc={calc} onReset={() => { setBill(""); setTip("10"); setPeople("4"); }} result={<Result label="Each person pays" value={`₹ ${(total / Math.max(1, n(people))).toFixed(2)}`} rows={[["Tip amount", `₹ ${tipAmount.toFixed(2)}`], ["Total bill", `₹ ${total.toFixed(2)}`], ["People", people || "1"]]} formula="(bill + tip) ÷ people" />}><div className="cn-field-grid"><Field label="Bill amount" value={bill} onChange={setBill} /><Field label="Tip (%)" value={tip} onChange={setTip} /><Field label="Number of people" value={people} onChange={setPeople} min="1" /></div></Frame>;
}
function PercentagePoints() {
  const calc = calcFor("percentage-points-calculator"); const [oldValue, setOldValue] = useState("18"); const [newValue, setNewValue] = useState("24"); const points = n(newValue) - n(oldValue); const relative = n(oldValue) ? points / n(oldValue) * 100 : 0;
  return <Frame calc={calc} onReset={() => { setOldValue(""); setNewValue(""); }} result={<Result label="Difference" value={`${points.toFixed(2)} percentage points`} rows={[["From", `${oldValue || 0}%`], ["To", `${newValue || 0}%`], ["Relative change", `${relative.toFixed(2)}%`]]} note="Percentage points compare the direct gap between two percentages." />}><div className="cn-field-grid two"><Field label="Original percentage" value={oldValue} onChange={setOldValue} /><Field label="New percentage" value={newValue} onChange={setNewValue} /></div></Frame>;
}

const CALC_COMPONENTS: Record<string, () => ReactNode> = { "basic-calculator": Basic, "percentage-calculator": Percentage, "emi-calculator": EMI, "sip-calculator": SIP, "gst-calculator": GST, "discount-calculator": Discount, "age-calculator": Age, "bmi-calculator": BMI, "bmr-calculator": BMR, "simple-interest-calculator": () => <Interest />, "compound-interest-calculator": () => <Interest compound />, "tip-calculator": Tip, "salary-calculator": Salary, "date-difference-calculator": DateDiff, "unit-converter": Converter, "currency-calculator": Currency, "fraction-calculator": Fraction, "average-calculator": Average, "ratio-calculator": Ratio, "scientific-calculator": Scientific, "loan-calculator": Loan, "savings-calculator": Savings, "tax-calculator": Tax, "calorie-calculator": Calorie, "ideal-weight-calculator": IdealWeight, "days-between-calculator": DaysBetween, "time-duration-calculator": TimeDuration, "fuel-cost-calculator": FuelCost, "electricity-cost-calculator": ElectricityCost, "split-bill-calculator": SplitBill, "percentage-points-calculator": PercentagePoints };
function CalculatorPage() { const { slug } = useParams<{ slug: string }>(); const Component = slug ? CALC_COMPONENTS[slug] : undefined; return Component ? <Component /> : <NotFound />; }

function InfoPage({ type }: { type: "about" | "privacy" | "terms" }) {
  const content = { about: { title: "A calmer place to calculate.", label: "About CalcNova", intro: "CalcNova was made for the moments when an answer should be simple, private, and close at hand.", sections: [["A useful kind of confidence", "Calculators should show their work without making you feel like you are back in a classroom. CalcNova pairs clear inputs with friendly results and the formula behind them."], ["Built for real life", "From comparing a salary offer to checking a tip, planning an investment, or counting down to a birthday, these are small decisions that deserve a good tool."], ["No account required", "Your calculations happen on your device. Favorites, recent tools, and your custom currency rates are kept in local browser storage."], ] }, privacy: { title: "Privacy, without the paperwork.", label: "Privacy policy", intro: "CalcNova is designed to work without accounts, servers, tracking, or external APIs.", sections: [["What stays on your device", "Theme preference, favorite calculators, recent calculator history, and editable currency rates are stored in your browser's localStorage. You can clear them from your browser settings at any time."], ["What we do not collect", "CalcNova does not ask for personal information and does not send your calculator inputs anywhere. Currency rates are manual and are never fetched live."], ["A note about health tools", "BMI and BMR are general educational estimates. They are not medical advice or a diagnosis. Consult a qualified professional for health decisions."]] }, terms: { title: "Simple terms for a simple tool.", label: "Terms of use", intro: "Use CalcNova freely for personal planning and everyday estimates.", sections: [["Use your judgment", "Results are estimates and should be checked against official statements, professional advice, or source documents when money, health, or legal decisions matter."], ["No warranties", "CalcNova is provided as-is. We work hard to keep formulas useful and the experience reliable, but cannot promise every result is suitable for every situation."], ["Respect the tool", "Do not attempt to disrupt, reverse engineer, or misuse the service. The calculator is free for ordinary personal and educational use."]] } }[type]; useMeta(content.title, content.intro); return <Shell><div className="cn-container"><article className="cn-prose"><SectionLabel>{content.label}</SectionLabel><h1 className="cn-display">{content.title}</h1><p style={{ fontSize: "1.05rem" }}>{content.intro}</p>{content.sections.map(([h, p]) => <section key={h}><h2>{h}</h2><p>{p}</p></section>)}</article></div></Shell>;
}
function Contact() { useMeta("Contact CalcNova", "Get in touch with the CalcNova team."); const [sent, setSent] = useState(false); return <Shell><div className="cn-container"><div className="cn-contact"><aside className="cn-contact-aside"><SectionLabel>Say hello</SectionLabel><h1 className="cn-display" style={{ fontSize: "clamp(2rem, 5vw, 3.7rem)", margin: "14px 0" }}>A better answer starts with a note.</h1><p>Found a rough edge, have a calculator idea, or want to tell us what you bookmark? We read every message.</p><div style={{ marginTop: 28, display: "flex", gap: 9, alignItems: "center", fontSize: ".82rem" }}><FileText size={17} /> hello@calcnova.example</div></aside><div className="cn-calculator-panel">{sent ? <div className="cn-empty"><ShieldCheck size={32} color="hsl(var(--accent))" /><h2 style={{ fontFamily: "var(--app-font-display)" }}>Message ready to go.</h2><p>Your email app can finish the conversation at hello@calcnova.example.</p><button className="cn-button cn-button-soft" onClick={() => setSent(false)} data-testid="button-send-another">Send another</button></div> : <form onSubmit={(e) => { e.preventDefault(); setSent(true); }}><div className="cn-panel-head"><div><div className="cn-kicker">Contact form</div><h2>What is on your mind?</h2></div></div><div className="cn-field-grid"><Field label="Your name" type="text" value="" onChange={() => undefined} placeholder="Your name" /><Field label="Email address" type="email" value="" onChange={() => undefined} placeholder="you@example.com" /></div><div className="cn-field" style={{ marginTop: 15 }}><label>Message</label><textarea className="cn-input" style={{ paddingTop: 12, minHeight: 130, resize: "vertical" }} placeholder="Tell us what would make CalcNova more useful." required data-testid="input-message" /></div><button className="cn-button cn-button-primary" style={{ marginTop: 18 }} type="submit" data-testid="button-submit-contact">Prepare message <ArrowRight size={16} /></button></form>}</div></div></div></Shell>; }

function Router() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Switch><Route path="/" component={Home} /><Route path="/calculator" component={Directory} /><Route path="/calculator/:slug" component={CalculatorPage} /><Route path="/about"><InfoPage type="about" /></Route><Route path="/privacy"><InfoPage type="privacy" /></Route><Route path="/terms"><InfoPage type="terms" /></Route><Route path="/contact" component={Contact} /><Route component={NotFound} /></Switch></ErrorBoundary>;
}
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, "")}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;